SELECT u.mobile as cell_phone, u.status, u.create_time, u.update_time, u.creator as creater, u.updater, u.id, u.username, u.user_type as type, u.real_name as name, u.gender, u.avatar as icon, u.email, ud.birthday, ud.introduction as intro FROM rk_user u LEFT JOIN rk_user_detail ud ON u.id = ud.user_id WHERE u.id
#{id}
AND u.is_deleted = 0
